INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Sitzungsschicht eine Ebene des OSI-Modells?', 2, '[{"text": "Ja", "correct": true, "because": "Schicht 5"}, {"text": "Nein", "correct": false, "because": "Sie ist Teil des Modells"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die Sitzungsschicht?', 3, '[{"text": "Sitzungen zwischen Anwendungen verwalten", "correct": true, "because": "Koordiniert Kommunikation"}, {"text": "Daten physisch übertragen", "correct": false, "because": "Schicht 1"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Schicht 6"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Sitzungsschicht ist Schicht 5. b) Sie ist für die physische Verbindung zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Schicht 1"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen gehören zur Sitzungsschicht?', 4, '[{"text": "Sitzungen einrichten", "correct": true, "because": "Startet Kommunikation"}, {"text": "Unklare Daten", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Sitzungen verwalten", "correct": true, "because": "Koordiniert Ablauf"}, {"text": "Sitzungen beenden", "correct": true, "because": "Schließt Kommunikation"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Kommunikation ohne Sitzungsschicht stattfinden?', 2, '[{"text": "Ja", "correct": true, "because": "Andere Schichten übernehmen"}, {"text": "Nein", "correct": false, "because": "Flexibilität möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Sitzungsschicht?', 3, '[{"text": "Koordination der Kommunikation", "correct": true, "because": "Verwaltet Sitzungen"}, {"text": "Daten physisch übertragen", "correct": false, "because": "Schicht 1"}, {"text": "Routing von Paketen", "correct": false, "because": "Schicht 3"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Sitzungsschicht nur für lokale Netzwerke relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch globale Netze"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat die Sitzungsschicht im OSI-Modell?', 3, '[{"text": "Dialogsteuerung zwischen Anwendungen", "correct": true, "because": "Koordiniert Sitzungen"}, {"text": "Adressvergabe", "correct": false, "because": "Schicht 3"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Schicht 6"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Sitzungsschicht synchronisiert Kommunikation. b) Sie überträgt Daten physisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Schicht 1"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Sitzungsschicht?', 3, '[{"text": "Sitzungen werden unstrukturiert", "correct": true, "because": "Koordination fehlt"}, {"text": "Datenübertragung unmöglich", "correct": false, "because": "Andere Schichten"}, {"text": "Netzwerk schneller", "correct": false, "because": "Unsinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Sitzungsschicht ohne Transportschicht arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Schicht 4"}, {"text": "Ja", "correct": false, "because": "Schichten verbunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Sitzungsschicht-Funktion?', 3, '[{"text": "Sitzung bei Dateiübertragung starten", "correct": true, "because": "Konkret und real"}, {"text": "Daten physisch senden", "correct": false, "because": "Schicht 1"}, {"text": "IP-Adresse zuweisen", "correct": false, "because": "Schicht 3"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Sitzungsschicht nur für Datenübertragung zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Verwaltet Sitzungen"}, {"text": "Ja", "correct": false, "because": "Koordination zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle arbeiten typischerweise auf der Sitzungsschicht?', 4, '[{"text": "NetBIOS", "correct": true, "because": "Verwaltet Sitzungen"}, {"text": "Unklare Protokolle", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "RPC", "correct": true, "because": "Remote Procedure Call"}, {"text": "PPTP", "correct": true, "because": "Point-to-Point Tunneling"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Sitzungsschicht immer aktiv sein?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anwendung"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat die Sitzungsschicht bei Verbindungen?', 3, '[{"text": "Sitzungen aufrechterhalten", "correct": true, "because": "Sichert Kommunikation"}, {"text": "Datenpakete routen", "correct": false, "because": "Schicht 3"}, {"text": "Physische Verbindung", "correct": false, "because": "Schicht 1"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Sitzungsschicht ohne Anwendungsschicht arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Anwendungen initiieren"}, {"text": "Ja", "correct": false, "because": "Schichten verbunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Sitzungsschicht?', 3, '[{"text": "Anwendungsanforderungen", "correct": true, "because": "Bestimmen Sitzungen"}, {"text": "Kabeltyp", "correct": false, "because": "Schicht 1"}, {"text": "Monitorgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Sitzungsschicht verwaltet mehrere Sitzungen. b) Sie ist für Hardware zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Schicht 1"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Sitzungsschicht?', 3, '[{"text": "Geordnete Kommunikation", "correct": true, "because": "Fördert Effizienz"}, {"text": "Maximale Unordnung", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Sitzungssteuerung", "correct": false, "because": "Fördert Verwaltung"}]');
